public static class AnagramNormalizer
{
    public static List<List<string>> Normalize(List<List<string>> groups)
    {
        var sorted = groups.Select(g => { var c = new List<string>(g); c.Sort(string.CompareOrdinal); return c; }).ToList();
        sorted.Sort((a, b) =>
        {
            for (var i = 0; i < Math.Min(a.Count, b.Count); i++)
            {
                var cmp = string.CompareOrdinal(a[i], b[i]);
                if (cmp != 0) return cmp;
            }
            return a.Count - b.Count;
        });
        return sorted;
    }
}

